    tasks[1] = { ...tasks[0], stem: 'İki öğrencinin felsefeye ilişkin tanımlarını özetleyiniz; hangi yönleri öncelikli gördüklerini ve bu farklılığın ortak tanım üzerinde uzlaşmayı nasıl güçleştirebileceğini açıklayınız.', key: `Vurgu karşılaştırması: ${a} ${b} Ortak tanım: ${f.inference} ${f.limit}` };
