    tasks[1] = { level: 'understand', stem: 'Metinde atlasın kayıtlı olduğu sonucuna götüren ifadeleri ve sonucu mantık terimleriyle adlandırarak çıkarımı açıklayınız; ardından ikinci ve üçüncü kişinin söylediklerinin neden bir argümanı güçlendirmediğini, ilgili kavramları adlandırarak kendi cümlelerinizle açıklayınız.', key: `Üç durumun açıklaması: ${key}`, criteria };
