    tasks[7] = { level: 'evaluate', stem: '“Sözcüğü olmayan şeyi düşünemeyiz” yargısının metindeki örneklerle desteklenen ve desteklenmeyen kısmını ayırınız; yargıyı metne uygun biçimde yeniden yazınız.', key: `${key} Yeniden yazım örneği: Sözcükler düşünceyi ayrıntılandırmaya katkı sağlayabilir; ancak bu örneklerden her düşünmenin sözcüğe bağlı olduğu sonucu çıkmaz.`, criteria: [criteria[0], criteria[1], 'Yargının metne uygun biçimde yeniden yazılması'] };
