    const situationCriteria: [string, string, string] = ['Metindekilerden farklı, ilişkiye uygun yeni bir durumun yazılması', 'Durumun ilişkiyi tutarlı biçimde göstermesi', 'Durumun metindeki hangi örnekle eşleştiğinin açıklanması'];
