    tasks[9] = { level: 'create', stem: 'Metindekilerden farklı, düşünme ile dil arasındaki ilişkiyi gösteren kısa bir durum yazınız; durumun metindeki hangi örnekle aynı ilişkiyi gösterdiğini açıklayınız.', key: `Örnek durum: ${f.example} Eşleşen örnek: şemayı cümleye dönüştürürken şemanın değişmesi (ifade etme çabasının düşünceyi etkilemesi); kavram ayrımı örneği (dilin düşünceyi düzenlemesi) ya da ikisi birlikte de kabul edilir. İlişki: ${f.inference} Özgün durumlar ve metindeki örnekle doğru eşleştirmeler kabul edilir.`, criteria: situationCriteria };
